<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter out = new BufferedWriter(new OutputStreamWriter(System.out));

        int n = Integer.parseInt(in.readLine());
        if (n > 11) {
            out.write("0\n");
            out.flush();
            in.close();
            out.close();
            return;
        }

        int[][] points = new int[n][5];
        for (int i = 0; i < n; i++) {
            String[] parts = in.readLine().split(" +");
            for (int j = 0; j < 5; j++) {
                points[i][j] = Integer.parseInt(parts[j]);
            }
        }

        List<Integer> candidates = new Vector<>();
        for (int pivot = 0; pivot < n; pivot++) {
            boolean valid = true;
            for (int a = 0; a < n && valid; a++) {
                if (a == pivot) continue;
                for (int b = 0; b < n && valid; b++) {
                    if (b == pivot || b == a) continue;

                    int[] vecA = new int[5];
                    int[] vecB = new int[5];
                    for (int dim = 0; dim < 5; dim++) {
                        vecA[dim] = points[a][dim] - points[pivot][dim];
                        vecB[dim] = points[b][dim] - points[pivot][dim];
                    }

                    long dot = 0;
                    for (int dim = 0; dim < 5; dim++) {
                        dot += (long)vecA[dim] * vecB[dim];
                    }

                    if (dot > 0) {
                        valid = false;
                    }
                }
            }

            if (valid) {
                candidates.add(pivot + 1);
            }
        }

        if (candidates.isEmpty()) {
            out.write("0\n");
        } else {
            out.write(candidates.size() + "\n");
            for (int idx : candidates) {
                out.write(idx + "\n");
            }
        }

        out.flush();
        in.close();
        out.close();
    }
}
